import { Component, OnInit } from '@angular/core';
import { FormArray, FormControl, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { AlertService } from 'src/app/services/alert.service';
import { UserService } from 'src/app/services/emis/user.service';
import { UserSessionService } from 'src/app/services/usersession.service';

@Component({
  selector: 'app-stem-leave',
  templateUrl: './stem-leave.page.html',
  styleUrls: ['./stem-leave.page.scss'],
})
export class StemLeavePage implements OnInit {
  form: FormGroup;
  allDate: any[];
  noDay: any;
  finalDate: any[] = [];
  active: boolean;
  username: any;
  constructor(private router: Router, private alertService: AlertService,private userService: UserService, private usersessionService: UserSessionService,
  ) { }

  ngOnInit() {
    this.initialValidator()
  }

  ionViewDidEnter() {
    this.username = this.usersessionService.emis_username();
    this.form.reset()
    this.userService.getCalendar().subscribe((response) => {
      this.allDate = response.result
      console.log(this.allDate, "response");
    })
  }

  onSelectDate(event) {
    var filter = this.allDate.filter((rq) => rq.date == event.detail.value);
    if (filter.length == 0) {
      this.form.controls['fromDate'].setValue('');
      this.form.controls['fromDate'].setValidators(Validators.required);
      this.form.controls['fromDate'].updateValueAndValidity();
      this.alertService.error("Please Select Valid Date")
    }
  }

  initialValidator() {
    this.form = new FormGroup({
      fromDate: new FormControl(Date, Validators.required),
      noDay: new FormControl("", Validators.required),
      session: new FormControl('', Validators.required),
      reason: new FormControl('', Validators.required),
    })
  }

  navigateBack() { this.router.navigate(['/tabs/leave-dashboard']); }

  onSave() {
    if (this.form.valid) {
      this.finalDate = []
      var noDay = this.form.controls['noDay'].value
      var noDate = this.form.controls['fromDate'].value
      for (var i = 1; i < this.allDate.length; i++) {
        if (this.allDate[i].date == noDate) {
            noDay = noDay * 2
          for (var n = 0; n < noDay; n++) {
            var count = count; 
            var session = count 
            this.active = false
            if(this.form.controls['session'].value == 1 && count == undefined){
              session = 1; count = 2;
              this.active = true
            }  else {
              if(count == 1){
                session = 1; count = 2;
                this.active = true
              }
            }
            if(this.form.controls['session'].value == 2  && count == undefined){
              session = 2; count = 1;
            } else {
              if(count == 2 && this.active == false) {
                session = 2; count = 1;
              }
            }
            var intDate;
            if(this.form.controls['session'].value == 1) { 
              intDate = (n) / 2
              intDate = parseInt(intDate)
            }
            if(this.form.controls['session'].value == 2) { 
              intDate = (n + 0.5) / 2
              intDate = Math.round(intDate)
            }
            var data1 = {
              "IndxID": "",
              "UserId": this.username,
              "LeaveDate": this.allDate[(i + intDate)].date,
              "Session": session,
              "Reason": this.form.controls['reason'].value,
              "ApprovedStatus": "1",
              "ApprovedBy": "1"
            }
              this.finalDate.push(data1)
          }
        }
      }
      
      let datas = {
        "records": this.finalDate
      }
      this.userService.leaveResponse(datas).subscribe((response) => {
        console.log(response);
        if(response.dataStatus){
          this.alertService.success("Leave Successfully Submitted")
          this.router.navigate(['/tabs/leave-dashboard']);
        } else {
          this.alertService.success(response.message)
        }
      })
    } else {
      this.validateAllFormFields(this.form);
      this.alertService.error("Please fill all the fields")
    }
  }

  validateAllFormFields(formGroup: any) {
    Object.keys(formGroup.controls).forEach(field => {
      const control = formGroup.get(field);
      if (control instanceof FormControl) {
        control.markAsTouched({ onlySelf: true });
      } else if (control instanceof FormGroup) {
        this.validateAllFormFields(control);
      } else if (control instanceof FormArray) {
        this.validateAllFormFields(control);
      }
    });
  }

}
